MeshNode::MeshNode(int id,
        gfsim::SimQueue<Packet>* localIn, gfsim::SimQueue<Packet>* localOut,
        gfsim::SimQueue<Packet>* westIn, gfsim::SimQueue<Packet>* westOut,
        gfsim::SimQueue<Packet>* eastIn, gfsim::SimQueue<Packet>* eastOut,
        gfsim::SimQueue<Packet>* northIn, gfsim::SimQueue<Packet>* northOut,
        gfsim::SimQueue<Packet>* southIn, gfsim::SimQueue<Packet>* southOut)
    : SimModule("node_" + std::to_string(id)),
      localIn_(localIn ? BindInput(localIn) : nullptr), localOut_(localOut ? BindOutput(localOut) : nullptr),
      westIn_(westIn ? BindInput(westIn) : nullptr), westOut_(westOut ? BindOutput(westOut) : nullptr),
      eastIn_(eastIn ? BindInput(eastIn) : nullptr), eastOut_(eastOut ? BindOutput(eastOut) : nullptr),
      northIn_(northIn ? BindInput(northIn) : nullptr), northOut_(northOut ? BindOutput(northOut) : nullptr),
      southIn_(southIn ? BindInput(southIn) : nullptr), southOut_(southOut ? BindOutput(southOut) : nullptr),
      id_(id)
{
    GFSIM_ASSERT(id >= 0 && id < kNodes);
    GFSIM_ASSERT(localIn_ && localOut_);
    GFSIM_ASSERT((westIn_ != nullptr) == (westOut_ != nullptr));
    GFSIM_ASSERT((eastIn_ != nullptr) == (eastOut_ != nullptr));
    GFSIM_ASSERT((northIn_ != nullptr) == (northOut_ != nullptr));
    GFSIM_ASSERT((southIn_ != nullptr) == (southOut_ != nullptr));
}

void MeshNode::Build()
{
    SetObjectCapacity(0);
    BuildInnerQueues();
    BuildChildren();
}

Direction MeshNode::Route(int node, int destination)
{
    if (node % kColumns < destination % kColumns) return Direction::East;
    if (node % kColumns > destination % kColumns) return Direction::West;
    if (node < destination) return Direction::South;
    if (node > destination) return Direction::North;
    return Direction::Local;
}

Direction MeshNode::Grant(Direction output, Direction last,
        Direction local, Direction west, Direction east, Direction north, Direction south)
{
    // Prefer the first requesting input after the previous winner, then wrap.
    if (last < Direction::Local && local == output) return Direction::Local;
    if (last < Direction::West && west == output) return Direction::West;
    if (last < Direction::East && east == output) return Direction::East;
    if (last < Direction::North && north == output) return Direction::North;
    if (last < Direction::South && south == output) return Direction::South;
    if (local == output) return Direction::Local;
    if (west == output) return Direction::West;
    if (east == output) return Direction::East;
    if (north == output) return Direction::North;
    if (south == output) return Direction::South;
    return Direction::None;
}

