void MeshNode::LogTransfer(int packetId, const std::string& output)
{
    if (auto* trace = Trace()) {
        const auto cycle = GetSim()->Cycles();
        trace->AddDuration(Path(), "forward", cycle - 1, cycle, output);
    }
    if (Log().Level() == gfsim::LogLevel::Debug) {
        Log().Debug(Name(), "forward") << "packet=" << packetId << " to " << output;
    }
}

void MeshNode::Xfer()
{
    AdvanceInnerQueues();
    XferChildren();
}

void MeshNode::Reset()
{
    lastLocal_ = Direction::None;
    lastWest_ = Direction::None;
    lastEast_ = Direction::None;
    lastNorth_ = Direction::None;
    lastSouth_ = Direction::None;
    forwarded_ = 0;
    ResetInnerQueues();
    ResetChildren();
}

void MeshNode::ReportStat()
{
    Report().ReportVal(Name() + " inter-node hops", forwarded_);
    ReportChildren();
}

